import re
from typing import List, Dict, Any, Tuple, Optional

# ----------------------------------------------------------------------
# Helper utilities (assumed to exist in the execution environment)
# ----------------------------------------------------------------------
# def node_by_title(doc, title): ...
# def node_by_id(doc, node_id): ...
# def children(doc, node): ...
# def scope_nodes(doc, scope): ...
# def table_rows(node): ...

# ----------------------------------------------------------------------
# Utility helpers
# ----------------------------------------------------------------------
def _first_numeric_id(text: str) -> Optional[str]:
    """Return the first numeric ID found in a string."""
    m = re.search(r'(\d+)', text)
    return m.group(1) if m else None

def _parse_event_line(line: str) -> Tuple[Optional[int], Optional[str], List[str]]:
    """Parse  `Frame N: ...` lines producing frame, event type, and object ids."""
    m = re.match(r'\s*Frame\s+(\d+):', line)
    if not m:
        return None, None, []
    frame = int(m.group(1))
    # enter / exit
    enter = re.search(r'Object (\d+).*?enters the scene', line)
    if enter:
        return frame, 'enter', [enter.group(1)]
    exit_ = re.search(r'Object (\d+).*?exits the scene', line)
    if exit_:
        return frame, 'exit', [exit_.group(1)]
    # collision
    coll = re.search(r'Object (\d+).*?collides with Object (\d+)', line)
    if coll:
        return frame, 'collision', [coll.group(1), coll.group(2)]
    return frame, None, []

