# Core functions
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """
    Return all distinct entities that the scope's records are about.
    Each entity is represented by a unique id and a full human‑readable description.
    """
    results: List[Dict[str, str]] = []
    seen: set[str] = set()
    for node in scope_nodes(doc, scope):
        if node.get("title", "").startswith("Objects"):
            for line in node.get("lines", []):
                m = re.match(r'Object\s+(\d+):\s+(.*?)(?:\s*\()', line)
                if m:
                    obj_id = m.group(1)
                    description = m.group(2).strip()
                    if obj_id not in seen:
                        seen.add(obj_id)
                        results.append({"id": obj_id, "description": description})
    return results


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """
    Return the last time point covered by the scope's records, expressed in frames.
    If the scope has no time data, return None.
    """
    max_frame: Optional[int] = None
    for node in scope_nodes(doc, scope):
        title = node.get("title", "")
        if title.startswith("Events"):
            for line in node.get("lines", []):
                m = re.match(r'\s*Frame\s+(\d+):', line)
                if m:
                    f = int(m.group(1))
                    if max_frame is None or f > max_frame:
                        max_frame = f
        elif title.startswith("Motion log"):
            for _, row in table_rows(node):
                f_str = row.get("frame")
                if f_str is None:
                    continue
                try:
                    f = int(f_str)
                except ValueError:
                    continue
                if max_frame is None or f > max_frame:
                    max_frame = f
    return float(max_frame) if max_frame is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Return a list of input records for the scope.
    """
    # Scan for first motion entry per object
    first_motion: Dict[str, Dict[str, Any]] = {}
    for node in scope_nodes(doc, scope):
        if node.get("title", "").startswith("Motion log"):
            for row_index, row in table_rows(node):
                obj_text = row.get("object", "")
                obj_id = _first_numeric_id(obj_text)
                if not obj_id:
                    continue
                try:
                    frame = int(row.get("frame", -1))
                    fields = {
                        "x": float(row.get("x", 0.0)),
                        "y": float(row.get("y", 0.0)),
                        "vx": float(row.get("vx", 0.0)),
                        "vy": float(row.get("vy", 0.0)),
                        "speed": float(row.get("speed", 0.0)),
                    }
                except Exception:
                    continue
                if obj_id not in first_motion or frame < first_motion[obj_id]["frame"]:
                    first_motion[obj_id] = {
                        "frame": frame,
                        "fields": fields,
                        "src": [node["node_id"], row_index],
                    }

    # Find enter events
    enter_events: Dict[str, int] = {}
    for node in scope_nodes(doc, scope):
        if node.get("title", "").startswith("Events"):
            for line_index, line in enumerate(node.get("lines", [])):
                frame, typ, objs = _parse_event_line(line)
                if typ == "enter" and objs:
                    enter_events[objs[0]] = frame

    # Build input records
    result: List[Dict[str, Any]] = []
    used_ids: set[str] = set()
    for obj_id, frame in enter_events.items():
        in_id = f"in_{obj_id}_arrival"
        if in_id in used_ids:
            continue
        used_ids.add(in_id)
        result.append(
            {
                "id": in_id,
                "time": float(frame),
                "kind": "arrival",
                "entities": [obj_id],
                "fields": {},
                "src": [node_by_title(doc, f"Video {scope}")["node_id"], frame],  # line index not available
            }
        )

    for obj_id, data in first_motion.items():
        if obj_id in enter_events:
            # Already handled as arrival
            continue
        in_id = f"in_{obj_id}_initial"
        if in_id in used_ids:
            continue
        used_ids.add(in_id)
        result.append(
            {
                "id": in_id,
                "time": float(data["frame"]),
                "kind": "initial_state",
                "entities": [obj_id],
                "fields": data["fields"],
                "src": data["src"],
            }
        )
    return result


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Return a list of outcome records for the scope.
    """
    outcomes: List[Dict[str, Any]] = []
    for node in scope_nodes(doc, scope):
        if node.get("title", "").startswith("Events"):
            for line_index, line in enumerate(node.get("lines", [])):
                frame, typ, objs = _parse_event_line(line)
                if typ in ("collision", "exit") and objs:
                    outcomes.append(
                        {
                            "time": float(frame),
                            "kind": typ,
                            "entities": objs,
                            "value": None,
                            "src": [node["node_id"], line_index],
                        }
                    )
    return outcomes


def params(doc: Dict[str, Any], scope: str) -> Dict[str, float]:
    """
    Return constants identified in the scope.
    The CLEVRER document does not list explicit constants.
