import re
from typing import Dict, List, Tuple, Any, Optional

# ----------------------------------------------------------------------
# Helper utilities (assumed available)
# ----------------------------------------------------------------------
# def node_by_title(doc, title) -> node
# def node_by_id(doc, node_id) -> node
# def children(doc, node) -> list[node]
# def scope_nodes(doc, scope) -> list[node]
# def table_rows(node) -> list[(row_index, dict[column, cell_str])]

# ----------------------------------------------------------------------
# Internal helpers
# ----------------------------------------------------------------------
def _obj_id(num: str) -> str:
    """Standard object internal id."""
    return f"obj_{num}"


def _parse_obj_line(line: str) -> Optional[Tuple[str, str]]:
    """
    Return (obj_num, description) for a line in an Objects list.
    Example line: 'Object 0: brown metal sphere (color=brown, material=metal, shape=sphere)'
    """
    m = re.match(r"Object\s+(\d+):\s+(.*)", line)
    if m:
        return m.group(1), m.group(2).strip()
    return None


def _parse_event_line(line: str) -> Optional[Tuple[int, str, List[str]]]:
    """
    Return (frame, event_type, [obj_nums]).
    event_type in {'enter', 'exit', 'collision'}.
    """
    header = re.match(r"\s*Frame\s+(\d+):", line)
    if not header:
        return None
    frame = int(header.group(1))

    enter = re.search(r"Object\s+(\d+)\s+.*?enters the scene", line)
    if enter:
        return frame, "enter", [enter.group(1)]

    exit_ = re.search(r"Object\s+(\d+)\s+.*?exits the scene", line)
    if exit_:
        return frame, "exit", [exit_.group(1)]

    coll = re.search(r"Object\s+(\d+)\s+.*?collides with Object\s+(\d+)", line)
    if coll:
        return frame, "collision", [coll.group(1), coll.group(2)]

    # line may describe presence at start (not an event outcome)
    return frame, "present", []


def _extract_motion_fields(row: Dict[str, str]) -> Dict[str, Any]:
    """Convert values from a motion log row to typed fields."""
    def parse_float(s: str) -> float:
        try:
            return float(s)
        except Exception:
            return 0.0

    return {
        "x": parse_float(row.get("x", "0")),
        "y": parse_float(row.get("y", "0")),
        "vx": parse_float(row.get("vx", "0")),
        "vy": parse_float(row.get("vy", "0")),
        "speed": parse_float(row.get("speed", "0")),
    }

# ----------------------------------------------------------------------
# Core functions
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return a list of distinct entities in the scope."""
    results: List[Dict[str, str]] = []
    seen: set[str] = set()
    for node in scope_nodes(doc, scope):
        if not node["title"].endswith("Objects"):
            continue
        for line in node["lines"]:
            parsed = _parse_obj_line(line)
            if not parsed:
                continue
            num, desc = parsed
            oid = _obj_id(num)
            if oid not in seen:
                seen.add(oid)
                results.append({"id": oid, "description": desc})
    return results


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last time point covered by the scope."""
    max_frame: Optional[int] = None

    for node in scope_nodes(doc, scope):
        # Events
        if node["title"].endswith("Events"):
            for line in node["lines"]:
                parsed = _parse_event_line(line)
                if parsed:
                    frame, _, _ = parsed
                    if max_frame is None or frame > max_frame:
                        max_frame = frame
        # Motion log
        elif node["title"].endswith("Motion log"):
            for idx, row in table_rows(node):
                try:
                    f = int(row.get("frame", ""))
                except Exception:
                    continue
                if max_frame is None or f > max_frame:
                    max_frame = f

    return float(max_frame) if max_frame is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all external inputs for the scope."""
    result: List[Dict[str, Any]] = []

    # Gather early appearances
    enter_times: Dict[str, int] = {}
    presence_lines: Dict[str, Tuple[int, str]] = {}  # obj_num -> (frame, node_id_line)

    for node in scope_nodes(doc, scope):
        if not node["title"].endswith("Events"):
            continue
        for idx, line in enumerate(node["lines"]):
            parsed = _parse_event_line(line)
            if not parsed:
                continue
            frame, evt, objs = parsed
            if evt == "enter" and objs:
                enter_times[objs[0]] = frame
            elif evt == "present" and objs == []:
                # mark that we saw a presence line for some objects? actually presence lines don't have obj id
                # These lines describe which objects are in view at frame 0, but they don't give specific ids
                # We skip, as we don't know which objects yet.
                pass

    # First motion records per object (for initial_state)
    earliest_motion: Dict[str, Tuple[int, Dict[str, Any], Tuple[Any, ...]]] = {}
    for node in scope_nodes(doc, scope):
        if not node["title"].endswith("Motion log"):
            continue
        for idx, row in table_rows(node):
            obj_col = row.get("object", "")
            m = re.match(r"(\d+)", obj_col)
            if not m:
                continue
            num = m.group(1)
            oid = _obj_id(num)
            try:
                frame = int(row.get("frame", "0"))
            except Exception:
                continue
            fields = _extract_motion_fields(row)
            src = ("node", node["node_id"], idx)
            if oid not in earliest_motion or frame < earliest_motion[oid][0]:
                earliest_motion[oid] = (frame, fields, src)

    # Build arrival inputs
    for obj_num, frame in sorted(enter_times.items(), key=lambda x: x[1]):
        oid = _obj_id(obj_num)
        inp = {
            "id": f"in_{oid}_arrival",
            "time": float(frame),
            "kind": "arrival",
            "entities": [oid],
            "fields": {},
            "src": ("node", node_by_title(doc, f"Video {int(scope[-5:])}").get("node_id", None), frame),
        }
        result.append(inp)

    # Build initial_state inputs (objects with motion but no enter event)
    for oid, (frame, fields, src) in earliest_motion.items():
        if oid in [f"obj_{n}" for n in enter_times]:
            continue  # already handled as arrival
        inp = {
            "id": f"in_{oid}_initial",
            "time": float(frame),
            "kind": "initial_state",
            "entities": [oid],
            "fields": fields,
            "src": src,
        }
        result.append(inp)

    return result


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all outcomes (collisions, exits) for the scope."""
    outcomes: List[Dict[str, Any]] = []

    for node in scope_nodes(doc, scope):
        if not node["title"].endswith("Events"):
            continue
        for idx, line in enumerate(node["lines"]):
            parsed = _parse_event_line(line)
            if not parsed:
                continue
            frame, evt, objs = parsed
            if evt in ("collision", "exit") and objs:
                outcomes.append({
                    "time": float(frame),
                    "kind": evt,
                    "entities": [ _obj_id(o) for o in objs ],
                    "value": None,
                    "src": ("node", node["node_id"], idx),
                })
    return outcomes


def params(doc: Dict[str, Any], scope: str) -> Dict[str, float]:
    """No explicit constants in this document."""
    return {}
